  set_sign:{title:'눈에 띄는 안내',day:16,when:s=>s.stories.includes('set_idea'),lines:[['아논','세트 메뉴 이름은 크게, 가격은 그 아래!'],['타키','가격도 멀리서 보여야지.'],['아논','앗, 너무 작았나? 그럼 다시 쓸게.'],['토모리','케이크 그림도… 있으면 좋을 것 같아.'],['아논','좋다. 토모린이 그려 줄래?'],['토모리','잘 그릴 수 있을지는 모르지만… 해 볼게.']]},
  set_test:{title:'식기 전에',day:17,when:s=>s.stories.includes('set_sign'),lines:[['타키','커피를 먼저 만들면 케이크를 담는 동안 식겠네.'],['소요','접시와 포크를 먼저 준비하면 어때?'],['타키','그다음 커피를 내리면 되겠다.'],['아논','오, 작업 순서도 정하는구나.'],['타키','주문이 한꺼번에 들어오면 이런 차이가 커.'],['소요','한 번 더 시간을 재 보자.']]},
  set_rana:{title:'라나의 시식',day:18,when:s=>s.stories.includes('set_test'),lines:[['라나','이거, 먹어도 돼?'],['타키','시식용이야. 뜨거운 건 조심하고.'],['라나','케이크랑 커피, 같이 먹는 거야?'],['아논','응. 공연 전에 조금 쉬어 가는 세트!'],['라나','그럼 쉬고 나서 기타 칠래.'],['타키','연습 시간만 늦지 마.']]},
  set_arrival:{title:'같은 시간에 몰려서',day:21,when:s=>specialDay()&&s.soldLiveSet>0&&s.stories.includes('set_test'),lines:[['타키','공연 시작 전이라 주문이 몰렸네.'],['아논','메뉴판을 보고 세트부터 고르는 사람이 많아.'],['소요','일반 주문도 섞여 있으니까, 먼저 들어온 것부터 확인하자.'],['타키','응. 완성된 건 식기 전에 먼저 나가야 해.'],['토모리','비어 있는 접시는 내가 모아 둘게.'],['타키','고마워, 토모리. 통로만 조심해.']]},
  set_sold_out:{title:'작게 적힌 품절',day:22,when:s=>specialDay()&&s.enabled.liveSet&&s.stock.cake===0&&s.stories.includes('set_idea'),lines:[['타키','케이크가 없어서 세트도 끝났어.'],['아논','품절 글씨가 작으면 줄 선 다음에야 알겠네.'],['타키','다음에는 메뉴 이름 옆에 크게 표시하자.'],['아논','응. 손님이 다른 걸 미리 고를 수도 있으니까.'],['타키','남은 음료 메뉴도 같이 보여 주면 좋겠다.'],['아논','그럼 내가 팻말을 뒤집을게. 이쪽에 크게 쓰면 되지?'],['타키','잠깐, 그렇게 하면 뒤에 적힌 공연 시간이 안 보여.'],['아논','아, 진짜네. 그럼 종이를 따로 붙여야겠다.'],['타키','응. 시간표는 그대로 두고, 세트 이름만 가리자.'],['아논','음료 가격도 옆에 적으면 손님이 다시 줄 안 서도 되겠네.'],['타키','가격은 메뉴판에 있으니까 화살표로 가리키면 돼.'],['아논','릿키는 글씨 적게 쓰는 쪽이 좋구나?'],['타키','마감할 때 떼기 쉬워야 하니까.'],['아논','알았어. 대신 화살표는 내가 예쁘게 그릴래.'],['타키','글씨 안 가리면 돼.']]},
  soundcheck:{title:'리허설과 주문표',day:24,when:s=>liveDay(),lines:[['타키','사운드 체크가 시작되면 주문 부르는 소리가 잘 안 들릴 수 있어.'],['아논','번호를 적어서 보여 주는 건 어때?'],['타키','좋네. 대신 숫자가 겹치지 않게 순서대로 써야 해.'],['아논','그 정도는 할 수 있거든? …아, 펜은 어디 있지?'],['타키','카운터 오른쪽.']]},
  after_live:{title:'공연이 끝난 뒤의 테이블',day:27,when:s=>liveDay(),lines:[['소요','공연 끝나고 앉아 있는 손님들이 많네.'],['타키','정리는 해야 하지만, 서둘러 내보내지는 말자.'],['아논','그럼 빈 테이블부터 치울까?'],['소요','응. 아직 이야기 중인 곳은 나중에 가자.'],['타키','잔은 한 번에 너무 많이 들지 마.'],['아논','알았어! 넘어뜨린 적 한 번도 없거든.']]},
  next_poster:{title:'다음 공연의 여백',day:29,when:s=>s.stories.includes('set_arrival'),lines:[['토모리','오늘 쓴 메뉴판, 지워야 해?'],['타키','날짜는 바꿔야 하지만 그림은 남겨도 될 것 같아.'],['아논','좋아. 밑에 다음 공연 날짜를 적을 수 있게 공간을 비워 두자.'],['토모리','응. 그럼 다음에도 쓸 수 있겠다.'],['타키','고생했어. 접어서 서랍에 넣어 둘게.'],['토모리','잠깐… 접으면 별 그림에 선이 생길 것 같아.'],['아논','아, 가운데에 그렸구나. 내가 날짜를 너무 아래에 썼나?'],['토모리','아니. 별 옆이 비어 있어서… 거기에 적으면 좋겠다고 생각했어.'],['타키','그럼 접지 말고 판 뒤에 끼워 두자.'],['아논','다음 날짜를 덧붙일 종이도 같이 넣어 놓을까?'],['타키','응. 근데 날짜 정해지기 전에는 적지 마.'],['아논','나도 그 정도는 알아!'],['토모리','다음 종이에도 별을 그려도 돼?'],['타키','응. 날짜가 보이게만 해 줘.'],['아논','그럼 난 토모린 그림 옆에 맞춰서 쓸게.']]}
